// Deterministic normalisation: the Switch must never see a free-text label.
// Unrecognised or failed classification falls through to 'general', which
// carries the unchanged appointment prompt.
const j = $json;
const raw = String(j.output ?? j.text ?? '').trim().toLowerCase();
// fold spaces, hyphens and punctuation to underscores so 'FTS Application',
// 'fts-application' and 'fts_application' all land on the same key
const norm = raw.replace(/[^a-z]+/g, '_').replace(/^_+|_+$/g, '');
// ORDER MATTERS in the substring fallback: 'fts_application' contains
// 'application', so the specific labels must be tested first.
const ALLOWED = ['fts_application', 'intellect_credits', 'tiering_appeals',
                 'reschedule', 'booking', 'application', 'general'];
let appointment_scenario = ALLOWED.includes(norm) ? norm : 'general';
if (appointment_scenario === 'general' && norm && norm !== 'general') {
  for (const a of ALLOWED) { if (norm.includes(a)) { appointment_scenario = a; break; } }
}
// drop the classifier's own output so it cannot be mistaken for a draft downstream
const { output, text, ...rest } = j;
return { json: { ...rest, appointment_scenario } };

