  search: $('Code - Split Out Questions').item.json.retrievalQuery,
  top: 6,
  queryType: 'semantic',
  semanticConfiguration: 'ucs-semantic-config',
  captions: 'extractive|highlight-false',
  answers: 'extractive|count-3',
  filter: `metadata/attributes/any(a: a/key eq 'sender_role' and a/value eq '${$('Code - Split Out Questions').item.json.sender_role}') and metadata/attributes/any(a: a/key eq 'intent' and a/value eq '${$('Code - Split Out Questions').item.json.intent}')`,
  select: 'id,content,reply_sent_at,metadata',
  vectorQueries: [
    {
      kind: 'vector',
      vector: $json.data?.[0]?.embedding,
      fields: 'content_vector',
      k: 6,
      exhaustive: false
    }
  ]
}) }}

parameters.jsCode:
// Flatten the Azure AI Search REST response into the precedent block that the
// disabled "AI Agent (Draft)" used to receive from its vector-store tool.
//
// runOnceForAllItems: one search response per inbound record, mapped 1:1 in
// input order.
// Degrades quietly: if the embed or search call was passed through by
// onError=continueRegularOutput, there is no `value` array, precedents is ''
// and the chain still drafts from the inbound email + thread history alone.
const searches = $input.all();
// This sub-workflow is invoked with the appointment records only, so pair
// against the trigger's items in input order.
const records  = $('Code - Split Out Questions').all();

// Every custom field lives inside metadata.attributes as a key/value string
// pair -- that is the node-compatible index schema, not top-level fields.
const attr = (d, k) => {
  const list = ((d || {}).metadata || {}).attributes || [];
  const hit = list.find(a => a && a.key === k);
  return hit && hit.value != null ? String(hit.value) : '';
};

const buildPrecedents = (docs) => docs.map((d, i) => {
  const question = String(d.content || '').trim();          // "Subject: ...\n\n<question>"
  const reply    = attr(d, 'reply_text').trim();
  const subject  = attr(d, 'reply_subject');
  const when     = String(d.reply_sent_at || attr(d, 'reply_sent_at') || '').slice(0, 10);
  if (!question && !reply) return '';
  return [
    `--- PRECEDENT ${i + 1}${when ? ` (replied ${when})` : ''} ---`,
    `PAST QUESTION:\n${question}`,
    `REPLY SUBJECT: ${subject}`,
    `REPLY SENT:\n${reply}`
  ].join('\n');
}).filter(Boolean).join('\n\n').slice(0, 24000);


// ---- Retrieval log fields (raw passthrough for the XLSX draft log) --------
// Taken straight from the search response: document ids in rank order, and
// each document's reranker|search score in the same order. No derived scoring.
const idsOf = (docs) => docs.map(d => String((d || {}).id || '')).filter(Boolean).join(', ');
const scoresOf = (docs) => docs.map(d => {
  const r = (d || {})['@search.rerankerScore'], s = (d || {})['@search.score'];
  return `${r == null ? '' : r}|${s == null ? '' : s}`;
}).join(', ');
// The filter sent by "HTTP - Retrieve Precedents", rebuilt from the same per-question
// record so the log shows what was searched. KEEP IN SYNC with that node.
const filterOf = (rec) =>
  `metadata/attributes/any(a: a/key eq 'sender_role' and a/value eq '${rec.sender_role}') and `
  + `metadata/attributes/any(a: a/key eq 'intent' and a/value eq '${rec.intent}')`;

return searches.map((s, i) => {
  const rec  = ((records[i] || {}).json) || {};
  const docs = Array.isArray((s.json || {}).value) ? s.json.value : [];
  return {
    json: {
      ...rec,
      precedents: buildPrecedents(docs),
      precedent_count: docs.length,
      precedent_ids: idsOf(docs),
      precedent_scores: scoresOf(docs),
      retrieval_filter: filterOf(rec),
      retrieval_docs: docs      // raw passthrough for inspection; dropped by the LLM chain
    },
    pairedItem: { item: i }
  };
});

// Fan out: one item per question. Each item is a full copy of the email record, so
// every WF-2a node downstream sees an ordinary record. queryText and retrievalQuery
// become the single question (with the Subject prefix WF-1b indexed); the full body is
// kept as original_queryText. intent is left as the parent classified it.
// email_index is the regroup key -- positional within this run, so it stays unique
// even when two emails share a thread.
const out = [];
$input.all().forEach((it, i) => {
  const rec = it.json || {};
  const subj = String(rec.inbound_subject || '');
  const body = String(rec.queryText || '').replace(/^Subject:[^\n]*\n\n/, '');
  const qs = Array.isArray(rec.questions) && rec.questions.length ? rec.questions : [body];
  qs.forEach((q, k) => {
    const text = `Subject: ${subj}\n\n${String(q)}`.slice(0, 8000);
    out.push({
      json: { ...rec, original_queryText: rec.queryText, question: String(q),
              question_index: k, question_total: qs.length, email_index: i,
              queryText: text, retrievalQuery: text },
      pairedItem: { item: i }
    });
  });
});
return out;

// Collapse the per-question answers back to one item per email.
//
// The base record is rebuilt from the TRIGGER (the email exactly as the parent sent it),
// so nothing added per question leaks into the returned record.
// Answers are matched by (email_index, question_index) -- never by position -- so the
// order the branches finish in cannot misalign them. A question with no answer is
// marked rather than dropped. Answers that came from a forward branch are marked as
// internal staff notes, identified by which record merge produced them.
const STRIP = /^Subject:[^\n]*\n\n/;
const safe = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const key = (j) => `${j.email_index}:${j.question_index}`;
const answerOf = (j) => {
  const o = j.output;
  return String(typeof o === 'string' ? o : ((o && (o.text || o.output)) || '')).trim();
};
// which forward branch (if any) each question went to
const forwarded = new Map();
for (const [n, branch] of [
  ['Merge - Record + Forward (Booking Staff)', 'booking_staff'],
  ['Merge - Record + Draft (Reschedule Counselling)', 'reschedule_counselling']
]) {
  for (const it of safe(n)) forwarded.set(key(it.json || {}), branch);
}
const got = new Map();
const contributors = new Map();
$input.all().forEach((it, idx) => {
  const j = it.json || {};
  if (j.email_index === undefined || j.question_index === undefined) return;
  got.set(key(j), j);
  if (!contributors.has(j.email_index)) contributors.set(j.email_index, []);
  contributors.get(j.email_index).push({ item: idx });
});
return $('When Executed by Another Workflow').all().map((em, e) => {
  const base = { ...(em.json || {}) };
  const body = String(base.queryText || '').replace(STRIP, '');
  const questions = Array.isArray(base.questions) && base.questions.length ? base.questions : [body];
  const rows = questions.map((question, q) => {
    const j = got.get(`${e}:${q}`) || {};
    return { question, j, answer: answerOf(j),
             forwarded: forwarded.has(`${e}:${q}`),
             branch: forwarded.get(`${e}:${q}`) || '',
             scenario: j.appointment_scenario || '' };
  });
  const collate_input = rows.map((r, i) => {
    const head = r.forwarded
      ? `ANSWER ${i + 1} (ROUTED TO A COLLEAGUE -- handover note):`
      : `ANSWER ${i + 1}:`;
    return `QUESTION ${i + 1}:\n\`\`\`\n${r.question}\n\`\`\`\n\n${head}\n\`\`\`\n` +
      `${r.answer || '(no answer was drafted for this question)'}\n\`\`\``;
  }).join('\n\n');
  const draft_type = rows.some(r => r.forwarded) ? 'forward' : 'reply';
  const precedents = rows.map((r, i) =>
    `--- QUESTION ${i + 1}${r.scenario ? ' [' + r.scenario + ']' : ''}: ${r.question} ---\n` +
    (r.j.precedents || '(no precedents retrieved)')
  ).join('\n\n').slice(0, 24000);
  // Retrieval log fields, one entry per question in question order ("Q1: ... | Q2: ...").
  // Each question was searched on its own, so they are kept apart rather than merged.
  const perQ = (f) => rows.map((r, i) =>
    `Q${i + 1}: ${r.j[f] == null ? '' : String(r.j[f])}`).join(' | ');
  return {
    json: { ...base, precedents,
            retrieval_queries: perQ('retrievalQuery'),
            retrieval_filter: perQ('retrieval_filter'),
            precedent_count: perQ('precedent_count'),
            precedent_ids: perQ('precedent_ids'),
            precedent_scores: perQ('precedent_scores'),
            collate_input: `DRAFT TYPE: ${draft_type}\n\n${collate_input}`,
            question_count: rows.length,
            // one draft per email: a forward (sender in CC) if any question was routed to a
            // colleague -- the first routed question decides which colleague -- else a reply
            draft_type,
            forward_branch: (rows.find(r => r.forwarded) || {}).branch || 'none',
            question_routes: rows.map(r => ({ scenario: r.scenario, forwarded: r.forwarded, branch: r.branch })) },
    pairedItem: contributors.get(e) || []
  };
});

// Returns the one draft each email produced: the collated reply, or -- when any of
// its questions was routed to a colleague -- a single forward with the sender in CC.
// Only the renderer the Switch chose runs for a given email; the others contribute
// nothing.
const safe = (name) => { try { return $(name).all(); } catch (e) { return []; } };
return [
  ...safe('Build Outlook HTML'),
  ...safe('Build Outlook Forward HTML (Booking Staff)'),
  ...safe('Build Outlook Forward HTML (Reschedule Counselling)'),
  ...safe('Build Outlook Forward HTML (FTS Application)')
];

// Build a BEAUTIFIED, email-client-safe HTML reply from AI Agent (Draft)'s
// PLAIN-TEXT output (field: output). The agent returns greeting + body with NO
// sign-off; this node parses that text into blocks (paragraphs / ordered /
// unordered), renders them with a table-based layout + inline styles (survives
// Outlook desktop, OWA, Graph sanitization, mobile), linkifies URLs + emails,
// applies **bold** / [text](url), then appends the fixed "Thank you." + signature
// + confidentiality footer. Deterministic - no LLM.
// Output field: html (consumed by Outlook - Create Reply Draft).

// ---- Theme (UCS house style: Word-generated Outlook mail) -----------------
// Mirrors the markup a real UCS sent reply carries: MsoNormal paragraphs,
// Aptos 11.5pt black body, [NUS Restricted] classification line, Calibri 10pt
// "::"-separated signature, red confidentiality notice. No card, no orange
// chrome -- the draft must look like it was typed in Outlook.
const FONT       = 'Aptos,sans-serif';
const SIG_FONT   = "'Calibri',sans-serif";
const ACCENT     = '#1F497D';   // signature blue
const TEXT       = 'black';
const MUTED      = '#1F497D';
const FAINT      = '#666666';
const CALLOUT_BG = 'yellow';    // review-note highlight (Word "background:yellow")
const LINK       = 'color:#467886; text-decoration:underline;';
