<p class="MsoNormal"><span style="font-size:10.0pt">&nbsp;</span></p>
<p class="MsoNormal">&nbsp;</p>`;

const TAIL = `</div></body></html>`;

// ---- Inline text: escape -> **bold** -> [text](url) -> bare URLs/emails ----
function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function inlineText(s){
  s = esc(s);
  s = s.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  const tokens = [];
  const stash = h => { tokens.push(h); return '\u0000' + (tokens.length - 1) + '\u0000'; };
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+|mailto:[^\s)]+)\)/g, (m,t,u) => stash('<a href="'+u+'" target="_blank" title="'+u+'">'+t+'</a>'));
  s = s.replace(/(https?:\/\/[^\s<]+[^\s<.,;:!?)\]])/g, (m,u) => stash('<a href="'+u+'" target="_blank" title="'+u+'">'+u+'</a>'));
  s = s.replace(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g, (m,e) => stash('<a href="mailto:'+e+'">'+e+'</a>'));
  s = s.replace(/\u0000(\d+)\u0000/g, (m,i) => tokens[+i]);
  return s;
}

// ---- Block renderers (MsoNormal paragraphs, Word-style) -------------------
// Lists are plain indented paragraphs with a hard-spaced marker, exactly like
// the "(a) ... (f)" blocks in a hand-written UCS reply. No table, no callout.
function renderOrdered(items){
  return items.map((txt,i) =>
    `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">${i+1}.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ${inlineText(txt)}</span></p>`
  ).join('\n');
}

function renderUnordered(items){
  return items.map(txt =>
    `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">&bull;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ${inlineText(txt)}</span></p>`
  ).join('\n');
}

function renderParagraph(lines){
  return `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">${lines.map(inlineText).join('<br>')}</span></p>`;
}

const GREETING = /^(hi|hello|hey|dear|good\s+(morning|afternoon|evening))\b.*$/i;

// ---- Sign-off detection (strip anything the agent appends as a closing) ----
// A whole line that is a valediction ("Best regards,", "Thanks", "Sincerely", ...).
const VALEDICTION = /^(thanks?(\s*(and|&)\s*regards)?|thank\s+you|many\s+thanks|best(\s+(regards|wishes))?|kind(est)?\s+regards|warm(est)?\s+regards|regards|sincerely|yours\s+(sincerely|faithfully|truly)|respectfully|cheers)[.,!\s]*$/i;
// A short trailing line that is a name / placeholder / team-or-org signature
// e.g. "[Your Name]", "Jane Tan", "University Counselling Service Team", "UCS Team".
const SIGN_NAME = /^(\[[^\]]*\]|[A-Z][A-Za-z.'\u2019-]*(?:\s+[A-Z][A-Za-z.'\u2019-]*){0,4}|(?:the\s+)?(?:ucs|front\s+desk|university\s+counsell?ing\s+services?)(?:\s+team)?|.*\bteam$)$/i;
// A valediction glued to the end of the last sentence ("...let us know. Best regards,").
const TRAIL_VALEDICTION = /[\s,;:-]+(thanks?(\s*(and|&)\s*regards)?|best\s+regards|kind\s+regards|warm\s+regards|regards|sincerely|cheers)[.,!\s]*$/i;

// ---- Deterministic greeting (replaces the agent's "Dear [Name]," placeholder) ----
const GREETING_WORD    = 'Dear';      // 'Hi' if preferred
const NAME_PLACEHOLDER = '[Name]';    // used when no name is found in the body OR the email address
// A greeting line to drop from the agent output (incl. bracketed "Dear [Name]," placeholders).
const STRIP_GREETING = /^(hi|hello|hey|dear|good\s+(morning|afternoon|evening))\b[\w\s.,'\[\]()\/-]{0,40},?\s*$/i;

const TITLES = /^(dr|mr|mrs|ms|miss|mx|prof|professor|assoc|a\/?prof|mdm|sir|madam)\.?$/i;
const BANNED = /^(ucs|university|counselling|counseling|services|service|front|desk|team|the|student|staff|clinician|sir|madam|dear|hi|hello|hey|regards|thanks|thank|best|kind|warm|warmest|sincerely|cheers|yours|wishes|cordially|respectfully|name|sender|to|whom|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december)$/i;
function titleCase(w){ return w ? w.charAt(0).toUpperCase() + w.slice(1).toLowerCase() : ''; }
function cleanFirst(cand){
  let toks = String(cand || '').trim().split(/\s+/).filter(Boolean);
  while (toks.length && TITLES.test(toks[0])) toks.shift();
  let f = (toks[0] || '').replace(/[^A-Za-z'\u2019-]/g,'');
  if (f.length < 2 || BANNED.test(f)) return '';
  return titleCase(f);
}
// Display names that are role/department mailboxes, not people.
const ORG_NAME = /\b(nus|ucs|yale|duke|office|dept|department|admin|administrator|registrar|admissions?|faculty|school|college|centre|center|team|services?|support|helpdesk|info|enquir\w*|inquir\w*|no[-\s]?reply|do[-\s]?not[-\s]?reply|notification|mailer|system|group|committee|society|library|bursar|finance)\b/i;

function firstNameFromDisplay(raw){
  let n = String(raw || '').trim();
  if (!n || n.indexOf('@') !== -1) return '';
  if (ORG_NAME.test(n)) return '';   // role mailbox -> fall through to the body, then [Name]
  if (/\d/.test(n)) return '';       // "Helpdesk 2", auto-provisioned accounts
  if (n.indexOf(',') !== -1){ const p = n.split(','); n = (p[1] || p[0]).trim(); } // "Last, First" -> First
  return cleanFirst(n);
}
function firstNameFromEmail(email){
  const local = String(email || '').split('@')[0] || '';
  const cand = (local.split(/[._+-]/)[0] || '');
  return /^[A-Za-z]{2,}$/.test(cand) ? titleCase(cand) : ''; // reject IDs like e0123456
}
// detect the name the sender signs with in their own message body (whitespace-collapsed)
const NAME   = "[A-Z][A-Za-z'\\u2019.\\-]+(?:\\s+[A-Z][A-Za-z'\\u2019.\\-]+){0,1}";
const STRONG = "(?:warmest\\s+regards|warm\\s+regards|kindest\\s+regards|kind\\s+regards|best\\s+regards|best\\s+wishes|thanks\\s+and\\s+regards|yours\\s+sincerely|yours\\s+faithfully|yours\\s+truly|sincerely|cordially)";
const WEAK   = "(?:regards|thank\\s+you|thanks|cheers|best)";
function firstNameFromBody(body){
  const s = String(body || '');
  if (!s) return '';
  let m, cand = '';
  const reStrong = new RegExp(STRONG + "\\s*[,!.:\\-\\u2013\\u2014]*\\s*(" + NAME + ")", 'gi');
  while ((m = reStrong.exec(s)) !== null) cand = m[1];   // strong sign-off: last wins
  let f = cleanFirst(cand);
  if (f) return f;
  cand = '';
  const reWeak = new RegExp(WEAK + "\\s*[,!.:\\-\\u2013\\u2014]*\\s*(" + NAME + ")", 'gi');
  while ((m = reWeak.exec(s)) !== null){                 // weak sign-off: only if name is at the very end
    const after = s.slice(m.index + m[0].length).replace(/[\s.,!]+/g,'');
    if (after.length <= 2) cand = m[1];
  }
  f = cleanFirst(cand);
  if (f) return f;
  const intro = s.slice(0, 400).match(new RegExp("(?:my name is|i am|i'm|this is)\\s+(" + NAME + ")", 'i'));
  return intro ? cleanFirst(intro[1]) : '';
}
function makeGreeting(displayName, email, bodyText){
  // Order of preference:
  // 1) the Outlook display name on the From address (From.emailAddress.name),
  //    unless it looks like a role/department mailbox or contains a digit
  // 2) else the name the sender signs with in their own incoming email body
  // 3) else the [Name] placeholder for the front-desk officer to fill in
  //
  // Display name first because "Clean Query (LLM)" strips sign-offs from the
  // body, so firstNameFromBody() only fires on "my name is ..." style text.
  const first = firstNameFromDisplay(displayName)
             // || firstNameFromEmail(email)          // optional: address local-part. NO trailing semicolon.
             || firstNameFromBody(bodyText);
  return first ? `${GREETING_WORD} ${first},` : `${GREETING_WORD} ${NAME_PLACEHOLDER},`;
}

// ---- Parse plain text into blocks -----------------------------------------
function buildBody(raw){
  let text = String(raw == null ? '' : raw);
  text = text.replace(/```[a-z]*\n?/gi,'').replace(/```/g,''); // drop code fences
  text = text.replace(/\r\n?/g,'\n').trim();

  // Strip a trailing sign-off / signature the agent may still emit. Walk up from the
  // end consuming blank / valediction / short name-or-team-or-placeholder lines (max 6);
  // if at least one valediction was seen, cut the whole region. Removes blocks like:
  //   Best regards,
  //   [Your Name]
  //   University Counselling Service Team
  {
    let tl = text.split('\n').map(l => l.replace(/\s+$/,''));
    while (tl.length && tl[tl.length-1].trim() === '') tl.pop();
    let i = tl.length - 1, hasVal = false, region = 0;
    while (i >= 0 && region < 6){
      const ln = tl[i].trim();
      if (ln === ''){ i--; region++; continue; }
      if (VALEDICTION.test(ln)){ hasVal = true; i--; region++; continue; }
      if (ln.length <= 60 && SIGN_NAME.test(ln)){ i--; region++; continue; }
      break;
    }
    if (hasVal){ tl.length = i + 1; text = tl.join('\n').replace(/\s+$/,''); }
  }

  const lines = text.split('\n');
  const blocks = [];
  let cur = null, blank = false;
  for (const raw2 of lines){
    const t = raw2.trim();
    // A blank line ends a PARAGRAPH but not a LIST. Models routinely put a blank
    // line between "1." and "2."; closing the block there gave each item its own
    // callout box with the counter restarting at 1. Only a non-list line (or a
    // change of list type) closes a list now.
    if (t === ''){ blank = true; continue; }
    const om = t.match(/^(?:\d+)[.)]\s+(.*)$/);
    const um = t.match(/^[-*\u2022\u00b7]\s+(.*)$/);
    if (om){
      if (!cur || cur.type !== 'ol'){ cur = { type:'ol', items:[] }; blocks.push(cur); }
      cur.items.push(om[1]);
    } else if (um){
      if (!cur || cur.type !== 'ul'){ cur = { type:'ul', items:[] }; blocks.push(cur); }
      cur.items.push(um[1]);
    } else {
      if (!cur || cur.type !== 'p' || blank){ cur = { type:'p', lines:[t] }; blocks.push(cur); }
      else { cur.lines.push(t); }
      if (GREETING.test(t) && cur.lines.length === 1){ cur = null; } // greeting stands alone
    }
    blank = false;
  }

  // Drop the agent's greeting line entirely - a deterministic greeting is prepended in
  // the emit step. This is what removes "Dear [Name]," (and any other agent greeting).
  if (blocks.length && blocks[0].type === 'p' && blocks[0].lines.length === 1 && STRIP_GREETING.test(blocks[0].lines[0])){
    blocks.shift();
  }

  // Fallback: trim a valediction glued onto the end of the last line
  // ("...do let us know. Best regards,") that the block strip above wouldn't catch.
  if (blocks.length){
    const lb = blocks[blocks.length - 1];
    if (lb.type === 'p' && lb.lines.length){
      lb.lines[lb.lines.length - 1] = lb.lines[lb.lines.length - 1].replace(TRAIL_VALEDICTION, '').trim();
      while (lb.lines.length && lb.lines[lb.lines.length - 1] === '') lb.lines.pop();
      if (!lb.lines.length) blocks.pop();
    }
  }

  const rendered = blocks.map(b => {
    if (b.type === 'ol') return renderOrdered(b.items);
    if (b.type === 'ul') return renderUnordered(b.items);
    return renderParagraph(b.lines);
  }).filter(Boolean);

  if (!rendered.length) rendered.push(SPACER);
  return rendered.join('\n' + SPACER + '\n');
}

// ---- Operating hours placeholder (deterministic) ---------------------------
// The reschedule-intake, booking and tiering-appeals aligners emit the literal
// token [[UCS_OPERATING_HOURS]] where the hours belong, and Collate Replies (LLM)
// carries it into the merged paragraph. It is swapped here for the Mon-Fri block
// resolved by the parent's "Code - Resolve Operating Hours" (passed in as
// ops.ucs_week_hours_block), so the hours text is never written by a model.
// The first token gets the block on lines of its own; any further tokens are
// dropped. The substituted text is written back to `output` so the parent's
// draft log shows real hours, not the token.
const HOURS_TOKEN = /\n?[ \t]*\[\[\s*UCS_OPERATING_HOURS\s*\]\][ \t]*\n?/g;
const HOURS_SCENARIOS = ['reschedule', 'booking', 'tiering_appeals'];
const HOURS_LEAD = 'Please take note of the operating hours for University Counselling Services this week:';
let WEEK_BLOCK = '';
try {
  WEEK_BLOCK = String($('When Executed by Another Workflow').first().json.ops.ucs_week_hours_block || '').trim();
} catch (e) { WEEK_BLOCK = ''; }

function applyHours(text, routes){
  const s = String(text == null ? '' : text);
  let seen = false;
  const replaced = s.replace(HOURS_TOKEN, () => {
    if (seen) return ' ';
    seen = true;
    return WEEK_BLOCK ? '\n' + WEEK_BLOCK + '\n' : ' ';
  });
  if (seen) return replaced;
  // Fallback: a reply with at least one in-scope, non-forwarded question whose
  // placeholder was lost still gets the hours, as their own paragraph at the end.
  const inScope = (Array.isArray(routes) ? routes : [])
    .some(r => r && !r.forwarded && HOURS_SCENARIOS.indexOf(r.scenario) !== -1);
  if (WEEK_BLOCK && inScope && s.trim()) {
    return s.replace(/\s+$/, '') + '\n\n' + HOURS_LEAD + '\n' + WEEK_BLOCK;
  }
  return s;
}

// ---- Emit -----------------------------------------------------------------
const all = $input.all();
const out = [];
for (let idx = 0; idx < all.length; idx++){
  const j = all[idx].json || {};
  // Per item. The record arriving here already carries every field Build Query
  // and Apply Intent produced, so read it off the item rather than reaching
  // back with .first() -- with N emails in one pass that gave every draft the
  // FIRST email's greeting, banner and redirect decision.
  const bq = j, fctx = j;

// ---- Forwarded-mail redirect decision (deterministic) ---------------------
// When a forward is a genuine handover (the Find Query agent set source =
// 'quoted'), the reply belongs to the person who originally wrote in, not to
// the colleague who forwarded it. The decision is made here; the native node
// "Outlook - Redirect Fwd Draft" (message: update) applies it to the draft
// that "Outlook - Create Reply Draft" just created.
//
// EVERY condition below must hold. Any failure degrades to today's behaviour
// (reply to the forwarder + review banner) -- never to a guessed recipient.
const EMAIL_RX = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i;
const OWN_MAILBOX = 'ucs@nus.edu.sg';
// Roles allowed to receive a redirected draft. 'staff' is excluded on purpose:
// a quoted block whose From: is an NUS department (bizauk@, hosteladmission@)
// is a forwarded official letter, not an enquirer. Add 'staff' to disable.
const REDIRECT_ROLES = ['student', 'visitor', 'external'];
// Same domain rules as Build Query / WF-1b -- keep in sync.
const roleFor = (address) => {
  const addr = String(address || '').trim().toLowerCase();
  const at = addr.lastIndexOf('@');
  const domain = at >= 0 ? addr.slice(at + 1) : '';
  if (!domain) return 'unknown';
  if (domain === 'u.nus.edu' || domain.endsWith('.u.nus.edu') ||
      domain === 'u.yale-nus.edu.sg' || domain.endsWith('.u.yale-nus.edu.sg') ||
      domain === 'u.duke.nus.edu' || domain.endsWith('.u.duke.nus.edu')) return 'student';
  if (domain === 'visitor.nus.edu.sg' || domain.endsWith('.visitor.nus.edu.sg') ||
      domain === 'partner.nus.edu.sg' || domain.endsWith('.partner.nus.edu.sg')) return 'visitor';
  if (domain === 'nus.edu.sg' || domain.endsWith('.nus.edu.sg')) return 'staff';
  return 'external';
};

const fwd_to    = String(fctx.fwd_original_sender || '').trim().toLowerCase();
const forwarder = String(fctx.inbound_from || '').trim().toLowerCase();
const fwd_redirect =
     fctx.is_forwarded === true
  && fctx.fwd_source === 'quoted'
  && EMAIL_RX.test(fwd_to)
  && fwd_to !== forwarder
  && fwd_to !== OWN_MAILBOX
  && REDIRECT_ROLES.indexOf(roleFor(fwd_to)) !== -1;

// Subject must START with FW:. Strip any existing RE:/FW: chain first, so a
// "RE: FW: x" inbound does not become "FW: RE: FW: x".
const SUBJ_PREFIX = /^(\s*(re|res|aw|sv|vs|antwort|fw|fwd|fwdd|tr|wg|rv|enc)\s*(\[\d+\])?\s*:\s*)+/i;
const fwd_subject = fwd_redirect
  ? ('FW: ' + String(fctx.inbound_subject || '').replace(SUBJ_PREFIX, '').trim()).slice(0, 255)
  : '';

// ---- Greeting -------------------------------------------------------------
// Non-redirected mail (normal + covering-source forwards): the sender's Outlook
// display name (inbound_from_name), falling back to the name they signed with
// in their own covering note, then to [Name]. For a covering-source forward the
// sender IS the person who wrote the query, so this is already correct.
//
// Redirected mail (fwd_source === 'quoted'): the draft now goes to the ORIGINAL
// enquirer, so greet them, not the forwarder. Same order of preference as
// makeGreeting: display name first, then their own text, then the address
// local-part. fwd_original_sender_name is the display name "Find Query Body
// (Agent)" read out of the quoted From: header -- it goes through the same
// ORG_NAME / digit / comma-swap guards as any other display name.
// inbound_from_name is deliberately NOT used here -- it is the forwarder.
let greetingLine;
if (fwd_redirect) {
  const f = firstNameFromDisplay(fctx.fwd_original_sender_name)
         || firstNameFromBody(fctx.queryText);
  greetingLine = f ? `${GREETING_WORD} ${f},` : `${GREETING_WORD} ${NAME_PLACEHOLDER},`;
} else {
  greetingLine = makeGreeting(bq.inbound_from_name, bq.inbound_from, bq.queryText);
}
const greetingHtml = renderParagraph([greetingLine]);

// ---- Forwarded-mail banner ------------------------------------------------
// Two distinct cases:
//  (a) redirect fired  -> To: and Subject were rewritten. Still flag it: an
//      auto-changed recipient on counselling mail must be eyeballed once.
//  (b) quoted but no redirect (guard failed / node disabled) -> the original
//      "check the recipient" banner, unchanged.
let bannerHtml = '';
const bannerBox = (inner) => `<p class="MsoNormal"><span style="font-size:11.5pt; background:yellow">
${inner}
    <span style="color:${FAINT};">Delete this highlighted note before sending.</span></span></p>
${SPACER}`;
if (fwd_redirect) {
  const fwdBy = esc(fctx.inbound_from_name || fctx.inbound_from || 'unknown sender');
  bannerHtml = bannerBox(`    <b style="color:${TEXT};">Recipient was changed automatically.</b><br>
    This email was forwarded by <b>${fwdBy}</b>. The draft has been re-addressed to the original enquirer <b>${esc(fwd_to)}</b> and the subject set to <b>${esc(fwd_subject)}</b>. Confirm the To: line is correct before sending.<br>`);
} else if (fctx.fwd_source === 'quoted') {
  const fwdBy = esc(fctx.inbound_from_name || fctx.inbound_from || 'unknown sender');
  const orig  = esc(fctx.fwd_original_sender || 'the original enquirer (address not detected)');
  bannerHtml = bannerBox(`    <b style="color:${TEXT};">Check the recipient before sending.</b><br>
    This email was forwarded by <b>${fwdBy}</b>, and the reply below was drafted in response to <b>${orig}</b>.
    The To: line on this draft is currently the forwarder &mdash; change it if the reply should go to the enquirer instead.<br>`);
}

  const srcField = j.output != null ? 'output' : (j.text != null ? 'text' : (j.html != null ? 'html' : ''));
  const raw = applyHours(srcField ? j[srcField] : '', j.question_routes);
  const body = buildBody(raw);
  // Blank MsoNormal paragraph after the greeting, as in a hand-written UCS reply.
  const full = HEAD + '\n' + bannerHtml + '\n' + greetingHtml + '\n' + SPACER + '\n' + body + '\n' + FOOTER + '\n' + TAIL;
  out.push({ json: { ...j, ...(srcField === 'output' ? { output: raw } : {}), outlookHtml: full, greeting: greetingLine, fwd_redirect, fwd_to, fwd_subject }, pairedItem: { item: idx } });
}
return out;

// Build a FORWARD note for booking requests raised by staff senders. Same
// deterministic renderer as "Build Outlook HTML (Appointment)" (identical
// esc/inlineText/list/paragraph helpers and the
// same buildBody parser) -- the ONLY differences are at the emit step:
//   * the message is addressed to the counselling team, not the enquirer, so
//     the greeting is a fixed "Dear Colleague," -- never the sender's name
//   * the LLM text is a handover note, and the ORIGINAL enquiry is appended
//     verbatim underneath in a quoted block, the way a real forward looks
