const GREETING_FWD = 'Dear Colleague,';
const SUBJ_PREFIX_FWD = /^(\s*(re|res|aw|sv|vs|antwort|fw|fwd|fwdd|tr|wg|rv|enc)\s*(\[\d+\])?\s*:\s*)+/i;
const FORWARD_TO = ''

// The original enquiry, rendered as a quoted block under the handover note.
function quotedOriginal(j){
  const from    = esc(j.inbound_from_name ? `${j.inbound_from_name} <${j.inbound_from}>` : (j.inbound_from || 'unknown sender'));
  const when    = esc(String(j.question_received_at || ''));
  const subject = esc(String(j.inbound_subject || ''));
  // queryText carries the "Subject: ...\n\n" prefix from Build Query -- strip it,
  // the subject is shown on its own row above.
  const body    = String(j.queryText || '').replace(/^Subject:[^\n]*\n+/, '');
  const rendered = buildBody(body);
  return `<div style="border:none; border-top:solid #E1E1E1 1.0pt; padding:3.0pt 0cm 0cm 0cm">
<p class="MsoNormal"><b><span style="font-size:11.0pt; font-family:${SIG_FONT}">From:</span></b><span style="font-size:11.0pt; font-family:${SIG_FONT}"> ${from}<br><b>Sent:</b> ${when}<br><b>Subject:</b> ${subject}</span></p>
</div>
${SPACER}
${rendered}`;
}

const all = $input.all();
const out = [];
for (let idx = 0; idx < all.length; idx++){
  const j = all[idx].json || {};

  const raw  = j.output != null ? j.output : (j.text != null ? j.text : (j.html != null ? j.html : ''));
  const note = buildBody(raw);

  // Fixed greeting: this message goes to the counselling team, so no sender
  // name resolution at all -- using the enquirer's name here would be wrong.
  const greetingHtml = renderParagraph([GREETING_FWD]);

  const fwd_out_subject = ('FW: ' + String(j.inbound_subject || '').replace(SUBJ_PREFIX_FWD, '').trim()).slice(0, 255);
  // Blank MsoNormal paragraph after the greeting, as in a hand-written UCS reply.
  const full = HEAD + '\n' + greetingHtml + '\n' + SPACER + '\n' + note + '\n' + quotedOriginal(j) + '\n' + FOOTER + '\n' + TAIL;

  out.push({
    json: {
      ...j,
      fwd_body_html:   full,
      fwd_out_subject,
      fwd_out_to:      FORWARD_TO,
      forward_reason:  'fts_application_completed',
      greeting:        GREETING_FWD
    },
    pairedItem: { item: idx }
  });
}
return out;

// Option A, step 2 of 3: put our rendered reply ABOVE Graph's native quote.
//
// Input is the draft returned by "HTTP - Create Reply Draft" (Graph
// createReply sent with no body), so body.content already holds Graph's own
// quote of the original: the From/Sent/To/Subject header block plus the
// original HTML. Our reply is read from the renderer via pairedItem.
//
// Deterministic, no LLM. While the HTTP nodes are disabled they pass the
// renderer's item straight through, so no draft arrives here: the item goes
// on with merge_status 'skipped_no_draft' and no draft_id.
//
// MODE: Run Once for Each Item.
const RENDERER = 'Build Outlook HTML';

const rec   = $(RENDERER).item.json;
const draft = $json;
const ours  = String(rec.outlookHtml || '');
const draftId = draft.isDraft === true ? String(draft.id || '') : '';
const body  = draft.body || {};
let graphHtml = String(body.content || '');

if (!draftId || !ours) {
  return { json: { id: '', draft_id: '', merged_body: '', merge_status: 'skipped_no_draft' } };
}

// Plain-text draft body (Prefer header not honoured): wrap it so it can sit in HTML.
if (String(body.contentType || '').toLowerCase() === 'text') {
  const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  graphHtml = '<html><head></head><body><div style="white-space:pre-wrap; font-family:Calibri,sans-serif; font-size:11pt">'
    + esc(graphHtml) + '</div></body></html>';
}

// Our pieces: the <style> block from our <head>, and everything inside our <body>.
const styleMatch = ours.match(/<style[\s\S]*?<\/style>/i);
const style = styleMatch ? styleMatch[0] : '';
const reply = ours
  .replace(/^[\s\S]*?<body[^>]*>/i, '')
  .replace(/<\/body>[\s\S]*$/i, '');

let merged = graphHtml;

// Style goes at the START of Graph's <head>, so any styles the original email
// carries come later and still win for the quoted part.
if (style) {
  if (/<head[^>]*>/i.test(merged)) merged = merged.replace(/<head[^>]*>/i, m => m + '\n' + style);
  else merged = style + '\n' + merged;
}

// Reply goes immediately after Graph's opening <body>, i.e. above the quote.
if (/<body[^>]*>/i.test(merged)) merged = merged.replace(/<body[^>]*>/i, m => m + '\n' + reply + '\n');
else merged = reply + '\n' + merged;

return { json: { id: draftId, draft_id: draftId, merged_body: merged, merge_status: 'merged' } };

