return { json: { id: draftId, draft_id: draftId, patch_payload, merge_status: 'merged', quote_cut } };

// Deterministic read of the yes/no answer. Anything unrecognised -- including a
// failed or empty classification passed through by continueRegularOutput --
// resolves to false, so the sender keeps the Student Portal link.
const j = $json;
const raw = String(j.output ?? j.text ?? '').trim().toLowerCase();
const is_exchange_student = /^y(es)?\b/.test(raw) || raw === 'true';
// drop the classifier's own output so it cannot be mistaken for a draft downstream
const { output, text, ...rest } = j;
return { json: { ...rest, is_exchange_student } };

// Deterministic read of the booking-stage label. Anything unrecognised --
// including a failed or empty classification -- resolves to new_request, which
// keeps the email on the existing Booking draft + Align Booking Reply path.
const j = $json;
const raw = String(j.output ?? j.text ?? '').trim().toLowerCase();
const norm = raw.replace(/[^a-z]+/g, '_').replace(/^_+|_+$/g, '');
const ALLOWED = ['portal_issue', 'new_request'];
const booking_stage = ALLOWED.find(a => norm === a) || ALLOWED.find(a => norm.includes(a)) || 'new_request';
// drop the classifier's own output so it cannot be mistaken for a draft downstream
const { output, text, ...rest } = j;
return { json: { ...rest, booking_stage } };
